static int
xmlXIncludeDoProcessRoot(xmlXIncludeCtxtPtr ctxt, xmlNodePtr tree) {
    int ret = 0;

    if ((tree == NULL) || (tree->type == XML_NAMESPACE_DECL))
	return(-1);
    if (ctxt == NULL)
	return(-1);

    if ((tree->doc != NULL) && (tree->doc->URL != NULL)) {
        ctxt->base = xmlStrdup((xmlChar *)tree->doc->URL);
        if (ctxt->base == NULL) {
            xmlXIncludeErrMemory(ctxt, tree, NULL);
            return(-1);
        }
    }

    ret = xmlXIncludeDoProcess(ctxt, tree);

static void
xmlXIncludeErrMemory(xmlXIncludeCtxtPtr ctxt, xmlNodePtr node,
                     const char *extra)
{
    ctxt->nbErrors++;
    __xmlRaiseError(NULL, NULL, NULL, ctxt, node, XML_FROM_XINCLUDE,
                    XML_ERR_NO_MEMORY, XML_ERR_ERROR, NULL, 0,
		    extra, NULL, NULL, 0, 0,
		    "Memory allocation failed : %s\n", extra);
    ctxt->errNo = XML_ERR_NO_MEMORY;
    ctxt->fatalErr = 1;
}

static int
xmlXIncludeDoProcessRoot(xmlXIncludeCtxtPtr ctxt, xmlNodePtr tree) {
    int ret = 0;

    if ((tree == NULL) || (tree->type == XML_NAMESPACE_DECL))
	return(-1);
    if (ctxt == NULL)
	return(-1);

    if ((tree->doc != NULL) && (tree->doc->URL != NULL)) {
        ctxt->base = xmlStrdup((xmlChar *)tree->doc->URL);
        if (ctxt->base == NULL) {
            xmlXIncludeErrMemory(ctxt);
            return(-1);
        }
    }

    ret = xmlXIncludeDoProcess(ctxt, tree);

static void
xmlXIncludeErrMemory(xmlXIncludeCtxtPtr ctxt)
{
    xmlRaiseMemoryError(ctxt->errorHandler, NULL, ctxt->errorCtxt,
                        XML_FROM_XINCLUDE, NULL);
}

xmlXIncludeCtxtPtr
xmlXIncludeNewContext(xmlDocPtr doc) {
    xmlXIncludeCtxtPtr ret;

    if (doc == NULL)
	return(NULL);
    ret = (xmlXIncludeCtxtPtr) xmlMalloc(sizeof(xmlXIncludeCtxt));
    if (ret == NULL)
	return(NULL);
    memset(ret, 0, sizeof(xmlXIncludeCtxt));
    ret->doc = doc;
    ret->incNr = 0;
    ret->incMax = 0;
    ret->incTab = NULL;
    ret->nbErrors = 0;
    return(ret);
}

xmlFuzzDataInit(data, size);
opts = (int) xmlFuzzReadInt(4);
opts |= XML_PARSE_XINCLUDE;
maxAlloc = xmlFuzzReadInt(4) % (size + 100);

xmlFuzzReadEntities();
docBuffer = xmlFuzzMainEntity(&docSize);
docUrl = xmlFuzzMainUrl();
if (docBuffer == NULL)
    goto exit;

/* Pull parser */

xmlFuzzMemSetLimit(maxAlloc);
ctxt = xmlNewParserCtxt();
if (ctxt != NULL) {
    xmlXIncludeCtxtPtr xinc;
    xmlDocPtr copy;

    doc = xmlCtxtReadMemory(ctxt, docBuffer, docSize, docUrl, NULL, opts);
    xmlFuzzCheckMallocFailure("xmlCtxtReadMemory",
                              ctxt->errNo == XML_ERR_NO_MEMORY);

    xmlFuzzResetMallocFailed();
    xinc = xmlXIncludeNewContext(doc);
    xmlXIncludeSetFlags(xinc, opts);
    xmlXIncludeProcessNode(xinc, (xmlNodePtr) doc);
    if (doc != NULL) {
        xmlFuzzCheckMallocFailure("xmlXIncludeProcessNode",
                xinc == NULL ||
                xmlXIncludeGetLastError(xinc) == XML_ERR_NO_MEMORY);
    }
    xmlXIncludeFreeContext(xinc);

void
xmlFuzzMemSetLimit(size_t limit) {
    fuzzNumAllocs = 0;
    fuzzMaxAllocs = limit;
    fuzzAllocFailed = 0;
}

void
xmlFuzzCheckMallocFailure(const char *func, int expect) {
    if (fuzzAllocFailed != expect) {
        fprintf(stderr, "%s: malloc failure %s reported\n",
                func, fuzzAllocFailed ? "not" : "erroneously");
        abort();
    }
}

static void LIBXML_ATTR_FORMAT(4,0)
xmlXIncludeErr(xmlXIncludeCtxtPtr ctxt, xmlNodePtr node, int error,
               const char *msg, const xmlChar *extra)
{
    int res;

    if (ctxt->fatalErr != 0)
        return;
    ctxt->nbErrors++;
    res = __xmlRaiseError(NULL, NULL, NULL, ctxt, node, XML_FROM_XINCLUDE,
                          error, XML_ERR_ERROR, NULL, 0,
		          (const char *) extra, NULL, NULL, 0, 0,
		          msg, (const char *) extra);

void
xmlXIncludeSetErrorHandler(xmlXIncludeCtxtPtr ctxt,
                           xmlStructuredErrorFunc handler, void *data) {
    if (ctxt == NULL)
        return;
    ctxt->errorHandler = handler;
    ctxt->errorCtxt = data;
}

static void LIBXML_ATTR_FORMAT(4,0)
xmlXIncludeErr(xmlXIncludeCtxtPtr ctxt, xmlNodePtr node, int error,
               const char *msg, const xmlChar *extra)
{
    int res;

    if (ctxt->fatalErr != 0)
        return;
    ctxt->nbErrors++;
    res = __xmlRaiseError(ctxt->errorHandler, NULL, ctxt->errorCtxt,
                          ctxt, node, XML_FROM_XINCLUDE, error, XML_ERR_ERROR,
                          NULL, 0, (const char *) extra, NULL, NULL, 0, 0,
		          msg, (const char *) extra);

static xmlDocPtr
xmlXIncludeParseFile(xmlXIncludeCtxtPtr ctxt, const char *URL) {
    xmlDocPtr ret = NULL;
    xmlParserCtxtPtr pctxt;
    xmlParserInputPtr inputStream;

    xmlInitParser();

    pctxt = xmlNewParserCtxt();
    if (pctxt == NULL) {
	xmlXIncludeErrMemory(ctxt);
	return(NULL);
    }
    if (ctxt->errorHandler != NULL)
        xmlCtxtSetErrorHandler(pctxt, ctxt->errorHandler, ctxt->errorCtxt);

